),

-- Step 3.1 (THEN branch): Create Column
step_3_1 AS (
  SELECT *, CONCAT([workday_employee_id], [workday_position_id]) AS [Workday ID & Position]
  FROM step_3
),

-- Step 3.2 (THEN branch): IF / THEN
-- Note: Do Not Display - Keep only rows that do not match this condition.
step_3_2 AS (
  SELECT *
  FROM step_3_1
  WHERE NOT ([comp_code] IN ('3332', '3336', '3350', '3362', '2421', '3088'))
),

-- Step 3.3 (THEN branch): IF / THEN
-- Note: Do Not Display - Keep only rows that do not match this condition.
step_3_3 AS (
  SELECT *
  FROM step_3_2
  WHERE NOT ([comp_code] IN ('3024', '3122', '3123', '3124', '3125', '3142', '3359') AND [emp_grp] IN ('1', '2', '3') AND [emp_subgrp] = '24')
),

-- Step 4: Reference DLP Contractual Data
step_4 AS (
  SELECT * FROM [DLP Contractual Data] AS [s9.cont]
),

-- Step 5: Join
step_5 AS (
  SELECT [wd.dvwsd].*,
         [sap.it41].[workday_employee_id],
         [sap.it41].[workday_position_id],
         [sap.it41].[dt1],
         [sap.it41].[date1],
         [sap.it41].[dt2],
