         [sap.it41].[date10],
         [sap.it41].[dt11],
         [sap.it41].[date11]
  FROM step_4 AS [wd.dvwsd]
  FULL OUTER JOIN [sap.it41] AS [sap.it41]
    ON [wd.dvwsd].[Workday ID & Position] = [sap.it41].[Workday ID & Position]
),

-- Step 6: Join
step_6 AS (
  SELECT [wd.dvwsd].*,
         [sap.hi0256].[persno],
         [sap.hi0256].[company_code_number],
         [sap.hi0256].[personnel_area],
         [sap.hi0256].[country_key_code]
  FROM step_5 AS [wd.dvwsd]
  LEFT JOIN [sap.hi0256] AS [sap.hi0256]
    ON [wd.dvwsd].[Workday ID & Position] = [sap.hi0256].[Workday ID & Position]
),

-- Step 7: Join
step_7 AS (
  SELECT [sap.hi0256].*,
         [s9.cont].[S9 ID] AS [S9 ID_s9.cont],
         [s9.cont].[Original Hire date] AS [Original Hire date_s9.cont],
         [s9.cont].[Recent Hire DAte] AS [Recent Hire DAte_s9.cont],
         [s9.cont].[Adjusted Service Date] AS [Adjusted Service Date_s9.cont]
  FROM step_6 AS [sap.hi0256]
  LEFT JOIN [s9.cont] AS [s9.cont]
    ON [sap.hi0256].[persno] = [s9.cont].[S9 ID]
),

-- Step 8: Create Column
step_8 AS (
